settings.custom_liquid:
{%- if collection -%}
  {%- liquid
    assign bc_parent_col = nil
    assign bc_show_parent = false
    assign bc_parent_label = nil
    assign bc_parent_url = nil

    assign mobile_back_label = 'Home'
    assign mobile_back_url = routes.root_url

    if collection.metafields.custom.parent_collectie.value != blank
      assign bc_parent_col = collection.metafields.custom.parent_collectie.value
    endif

    if bc_parent_col != blank
      assign bc_show_parent = true
      assign bc_parent_label = bc_parent_col.title
      assign bc_parent_url = bc_parent_col.url

      assign mobile_back_label = bc_parent_col.title
      assign mobile_back_url = bc_parent_col.url
    endif
  -%}

  <div class="rt-bc-mobile-back page-width">
    <a class="rt-bc-mobile-back__link" href="{{ mobile_back_url }}">
      <span class="rt-bc-mobile-back__icon" aria-hidden="true">
        <svg width="7" height="10" viewBox="0 0 7 10" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M1 9L5 5L1 1" stroke="currentColor" stroke-width="2"></path>
        </svg>
      </span>
      <span>{{ mobile_back_label }}</span>
    </a>
  </div>

  <div class="rt-bc-outer page-width">
    <nav class="rt-bc" aria-label="Breadcrumb">
      <ol class="rt-bc__list" role="list">

        <li class="rt-bc__item">
          <a class="rt-bc__link rt-bc__home" href="{{ routes.root_url }}" aria-label="Home">
            <span class="rt-bc__home-ico" aria-hidden="true">
              <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true">
                <path d="M3.012,10.981,3,11H5v9a1,1,0,0,0,1,1H18a1,1,0,0,0,1-1V11h2a1,1,0,0,1,.555-1.832l-9-6a1,1,0,0,0-1.11,0l-9,6a1,1,0,0,0-.277,1.387A.98.98,0,0,0,3.012,10.981ZM10,14a1,1,0,0,1,1-1h2a1,1,0,0,1,1,1v5H10Z"></path>
              </svg>
            </span>
          </a>
        </li>

        <li class="rt-bc__sep" aria-hidden="true">
          <svg width="7" height="10" viewBox="0 0 7 10" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M1 9L5 5L1 1" stroke="currentColor" stroke-width="2"></path>
          </svg>
        </li>

        {%- if bc_show_parent and bc_parent_label and bc_parent_url -%}
          <li class="rt-bc__item">
            <a class="rt-bc__link" href="{{ bc_parent_url }}">{{ bc_parent_label }}</a>
          </li>
          <li class="rt-bc__sep" aria-hidden="true">
            <svg width="7" height="10" viewBox="0 0 7 10" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M1 9L5 5L1 1" stroke="currentColor" stroke-width="2"></path>
            </svg>
          </li>
        {%- endif -%}

        <li class="rt-bc__item">
          <span class="rt-bc__current" aria-current="page">{{ collection.title }}</span>
        </li>

      </ol>
    </nav>
  </div>

  <style>
    .rt-bc-mobile-back{
      display: none;
    }

    .rt-bc-outer{
      width: 100% !important;
      max-width: var(--page-width, 1200px);
      margin: 0 auto !important;
      background: #EDF0F2;
      padding: 12px 12px 12px 16px !important;
      border-radius: 0 !important;
      text-align: left !important;
      justify-self: start !important;
      align-self: start !important;
      place-self: start !important;
    }

    .rt-bc{
      margin: 0 !important;
      padding: 0 !important;
      width: 100% !important;
      text-align: left !important;
      font-family: inherit;
      font-size: 14px;
      font-weight: 500;
      line-height: 1.2;
      color: #003878;
    }

    .rt-bc__list{
      display: flex;
      justify-content: flex-start !important;
      align-items: center;
      gap: 8px;
      margin: 0 !important;
      padding: 0 !important;
      list-style: none !important;
      width: 100% !important;
      flex-wrap: wrap;
    }

    .rt-bc__item{
      min-width: 0;
    }

    .rt-bc__link{
      color: #003878;
      text-decoration: none;
      transition: color .15s ease, text-decoration-color .15s ease;
      display: inline-flex;
      align-items: center;
      gap: 6px;
    }

    .rt-bc__link:hover{
      color: #FF7300;
      text-decoration: underline;
      text-decoration-color: #FF7300;
    }

    .rt-bc__home-ico{
      display: inline-flex;
      line-height: 0;
    }

    .rt-bc__home-ico svg{
      display: block;
      width: 16px;
      height: 16px;
      fill: currentColor;
    }

    .rt-bc__sep{
      color: #003878;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      line-height: 0;
      flex: 0 0 auto;
    }

    .rt-bc__sep svg{
      display: block;
      width: 7px;
      height: 10px;
    }

    .rt-bc__current{
      color: #003878;
      font-size: 14px;
      font-weight: 500;
    }

    .rt-bc-mobile-back__link{
      color: #003878;
      text-decoration: none;
      font-size: 14px;
      font-weight: 500;
      line-height: 1.2;
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }

    .rt-bc-mobile-back__link:hover{
      color: #FF7300;
      text-decoration: underline;
    }

    .rt-bc-mobile-back__icon{
      display: inline-flex;
      align-items: center;
      justify-content: center;
      line-height: 0;
      transform: rotate(180deg);
      flex: 0 0 auto;
    }

    .rt-bc-mobile-back__icon svg{
      display: block;
      width: 7px;
      height: 10px;
    }

    @media (max-width: 749px){
      .rt-bc-outer{
        display: none !important;
      }

      .rt-bc-mobile-back{
        display: block;
        width: 100vw !important;
        max-width: none !important;
        margin-left: calc(50% - 50vw) !important;
        margin-right: calc(50% - 50vw) !important;
        background: #EDF0F2;
        padding: 12px 10px 12px 12px !important;
        box-sizing: border-box;
      }
    }
  </style>
{%- endif -%}

{% if collection %}
  {% liquid
    assign max_pills = 15
    assign text_short = 'Op zoek naar technisch advies, een specifieke maat of een niet-standaard oplossing? Ons ervaren team staat voor je klaar en denkt graag met je mee om tot de beste oplossing te komen.'
    assign text_long_default = 'Ben je op zoek naar technisch advies, een specifieke maat of een oplossing die niet standaard op de website staat? Ons ervaren team helpt je graag verder. We denken met je mee, geven deskundig advies en kijken samen naar de beste oplossing voor jouw situatie.'

    assign type_key = 'filter.p.product_type'
    assign merk_key = 'filter.p.vendor'
    assign kleur_key = 'filter.v.t.shopify.color-pattern'
    assign aantal_key = 'filter.p.m.custom.aantal_stuks_in_pakket'

    assign show_filters = false

    for f in collection.filters
      assign eligible_count = 0

      if f.param_name == type_key
        for v in f.values
          if v.count > 0 and v.active == false
            assign eligible_count = eligible_count | plus: 1
          endif
        endfor
        if eligible_count > 0
          assign show_filters = true
          break
        endif
      endif

      if f.param_name == merk_key
        for v in f.values
          if v.count > 0 and v.active == false and v.label != 'Merkloos'
            assign eligible_count = eligible_count | plus: 1
          endif
        endfor
        if eligible_count > 0
          assign show_filters = true
          break
        endif
      endif

      if f.param_name == kleur_key
        assign kleur_count = 0
        for v in f.values
          if v.count > 0
            assign kleur_count = kleur_count | plus: 1
          endif
        endfor
        if kleur_count > 1
          assign show_filters = true
          break
        endif
      endif

      if f.param_name == aantal_key
        assign aantal_count = 0
        for v in f.values
          if v.count > 0
            assign aantal_count = aantal_count | plus: 1
          endif
        endfor
        if aantal_count > 1
          assign show_filters = true
          break
        endif
      endif
    endfor
  %}

  {% capture pills_html %}
    {% assign render_slots = max_pills %}
    {% if render_slots > 0 %}
      {% for f in collection.filters %}
        {% if f.param_name == type_key %}
          {% assign sorted_types = f.values | sort: 'count' | reverse %}
          {% for v in sorted_types %}
            {% if render_slots <= 0 %}{% break %}{% endif %}
            {% if v.count > 0 and v.active == false %}
              <a class="cw-pill" href="{{ v.url_to_add }}" data-filter-key="{{ type_key | escape }}" data-filter-val="{{ v.value | escape }}">
                <span class="cw-pill-type">Type</span><span class="cw-pill-val">{{ v.label }}</span>
              </a>
              {% assign render_slots = render_slots | minus: 1 %}
            {% endif %}
          {% endfor %}
          {% break %}
        {% endif %}
      {% endfor %}
    {% endif %}
    {% if render_slots > 0 %}
      {% for f in collection.filters %}
        {% if f.param_name == merk_key %}
          {% for v in f.values %}
            {% if render_slots <= 0 %}{% break %}{% endif %}
            {% if v.count > 0 and v.active == false and v.label != 'Merkloos' %}
              <a class="cw-pill" href="{{ v.url_to_add }}" data-filter-key="{{ merk_key | escape }}" data-filter-val="{{ v.value | escape }}">
                <span class="cw-pill-type">Merk</span><span class="cw-pill-val">{{ v.label }}</span>
              </a>
              {% assign render_slots = render_slots | minus: 1 %}
            {% endif %}
          {% endfor %}
          {% break %}
        {% endif %}
      {% endfor %}
    {% endif %}
    {% if render_slots > 0 %}
      {% for f in collection.filters %}
        {% if f.param_name == kleur_key %}
          {% assign kleur_count = 0 %}
          {% for v in f.values %}
            {% if v.count > 0 %}{% assign kleur_count = kleur_count | plus: 1 %}{% endif %}
          {% endfor %}
          {% if kleur_count > 1 %}
            {% for v in f.values %}
              {% if render_slots <= 0 %}{% break %}{% endif %}
              {% if v.count > 0 and v.active == false %}
                <a class="cw-pill" href="{{ v.url_to_add }}" data-filter-key="{{ kleur_key | escape }}" data-filter-val="{{ v.value | escape }}">
                  <span class="cw-pill-type">Kleur</span><span class="cw-pill-val">{{ v.label }}</span>
                </a>
                {% assign render_slots = render_slots | minus: 1 %}
              {% endif %}
            {% endfor %}
          {% endif %}
          {% break %}
        {% endif %}
      {% endfor %}
    {% endif %}
    {% if render_slots > 0 %}
      {% for f in collection.filters %}
        {% if f.param_name == aantal_key %}
          {% assign aantal_count = 0 %}
          {% for v in f.values %}
            {% if v.count > 0 %}{% assign aantal_count = aantal_count | plus: 1 %}{% endif %}
          {% endfor %}
          {% if aantal_count > 1 %}
            {% for v in f.values %}
              {% if render_slots <= 0 %}{% break %}{% endif %}
              {% if v.count > 0 and v.active == false %}
                <a class="cw-pill" href="{{ v.url_to_add }}" data-filter-key="{{ aantal_key | escape }}" data-filter-val="{{ v.value | escape }}">
                  <span class="cw-pill-type">Aantal</span>
                  {% if v.label == '1' %}
                    <span class="cw-pill-stuks">1 stuk</span>
                  {% else %}
                    <span class="cw-pill-stuks">{{ v.label }} stuks</span>
                  {% endif %}
                </a>
                {% assign render_slots = render_slots | minus: 1 %}
              {% endif %}
            {% endfor %}
          {% endif %}
          {% break %}
        {% endif %}
      {% endfor %}
    {% endif %}
  {% endcapture %}

<style>
  /* ===================== GEDEELD ===================== */
  .cw-pill {
    display: inline-flex;
    align-items: center;
    padding: 14px 8px;
    gap: 4px;
    font-size: 14px;
    flex-shrink: 0;
  }
  .cw-pill[hidden] { display: none; }
  .cw-pill-type { color: #7D98AA; font-weight: 400; }
  .cw-pill-val { font-weight: 600; }
  .cw-pill-stuks { font-weight: 600; color: #003878; }
  .cw-pill:hover .cw-pill-val,
  .cw-pill:hover .cw-pill-stuks { color: inherit; }
  .cw-pill:hover .cw-pill-type { color: #7D98AA; }

  .cw-row {
    display: flex;
    flex-wrap: nowrap;
    gap: 8px;
    overflow-x: auto;
    scrollbar-width: none;
    -ms-overflow-style: none;
  }
  .cw-row::-webkit-scrollbar { display: none; }

  /* ===================== DESKTOP ===================== */
  .cw-desktop { display: block; }
  .cw-mobile  { display: none; }

  .cw-desktop .cw-inner {
    display: flex;
    flex-direction: row;
    align-items: stretch;
  }
  .cw-desktop .cw-image {
    width: 310px;
    min-width: 310px;
    height: 220px;
    overflow: hidden;
    flex-shrink: 0;
    background-color: #ffffff;
  }
  .cw-desktop .cw-image__img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
    object-position: center;
  }
  .cw-desktop .cw-body {
    flex: 1;
    min-width: 0;
    padding-left: 0;
    padding-right: var(--page-width-padding, var(--bs-gutter-x, 20px));
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    align-items: flex-start;
    overflow: hidden;
  }
  .cw-desktop .cw-image + .cw-body { padding-left: 24px; }
  .cw-desktop .cw-text {
    flex: 1;
    display: flex;
    align-items: center;
    width: 100%;
  }
  .cw-desktop .cw-text-content { width: 100%; }
  .cw-desktop .cw-filters {
    margin-top: 16px;
    width: 100%;
    overflow: hidden;
  }
  .cw-desktop .cw-quickfilters { width: 100%; overflow: hidden; }
  .cw-desktop .cw-scrollwrap { width: 100%; overflow: hidden; position: relative; }

  @media screen and (max-width: 989px) {
    .cw-desktop .cw-image {
      width: 240px;
      min-width: 240px;
      height: 180px;
    }
  }

  /* ===================== MOBIEL ===================== */
  @media screen and (max-width: 768px) {
    .cw-desktop { display: none; }
    .cw-mobile  { display: block; }

    .cw-mobile .cw-inner {
      display: block;
    }
    .cw-mobile .cw-filters {
      margin-top: 24px;
      margin-left: calc(-1 * var(--page-width-padding, var(--bs-gutter-x, 20px)));
      margin-right: calc(-1 * var(--page-width-padding, var(--bs-gutter-x, 20px)));
      overflow: visible;
    }
    .cw-mobile .cw-quickfilters,
    .cw-mobile .cw-scrollwrap {
      overflow: visible;
    }
    .cw-mobile .cw-row {
      padding-left: 0;
      padding-right: var(--page-width-padding, var(--bs-gutter-x, 20px));
    }
  }
</style>

  <!-- ===================== DESKTOP HTML ===================== -->
  <section class="cw-collection-header cw-desktop" data-cw-header>
    <div class="cw-inner">
      {% if collection.image %}
        <div class="cw-image">
          {{
            collection.image
            | image_url: width: 1200
            | image_tag:
              class: 'cw-image__img',
              widths: '310, 480, 720',
              sizes: '(max-width: 989px) 240px, 310px',
              alt: collection.title,
              loading: 'eager',
              fetchpriority: 'high'
          }}
        </div>
      {% endif %}
      <div class="cw-body">
        <div class="cw-text">
          <div class="cw-text-content">
            <h1 class="cw-title">{{ collection.title }}</h1>
            {% if show_filters %}
              <div class="cw-desc">{{ text_short }}</div>
            {% else %}
              <div class="cw-desc">
                {% if collection.metafields.custom.collection_intro != blank %}
                  {{ collection.metafields.custom.collection_intro | metafield_tag }}
                {% else %}
                  {{ text_long_default }}
                {% endif %}
              </div>
            {% endif %}
          </div>
        </div>
        {% if show_filters %}
          <div class="cw-filters">
            <div class="cw-quickfilters">
              <div class="cw-scrollwrap">
                <button class="cw-navbtn cw-navbtn--left" type="button" aria-label="Scroll left" data-cw-left hidden>
                  <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M15 18l-6-6 6-6"></path></svg>
                </button>
                <button class="cw-navbtn cw-navbtn--right" type="button" aria-label="Scroll right" data-cw-right hidden>
                  <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M9 6l6 6-6 6"></path></svg>
                </button>
                <div class="cw-row" role="navigation" aria-label="Quick filters" data-cw-row>
                  {{ pills_html }}
                </div>
              </div>
            </div>
          </div>
        {% endif %}
      </div>
    </div>
  </section>

  <!-- ===================== MOBIEL HTML ===================== -->
  <section class="cw-collection-header cw-mobile" data-cw-header>
    <div class="cw-inner page-width">
      <div class="cw-text">
        <div class="cw-text-content">
          <h1 class="cw-title">{{ collection.title }}</h1>
          {% if show_filters %}
            <div class="cw-desc">{{ text_short }}</div>
          {% else %}
            <div class="cw-desc">
              {% if collection.metafields.custom.collection_intro != blank %}
                {{ collection.metafields.custom.collection_intro | metafield_tag }}
              {% else %}
                {{ text_long_default }}
              {% endif %}
            </div>
          {% endif %}
        </div>
      </div>
      {% if show_filters %}
        <div class="cw-filters">
          <div class="cw-quickfilters">
            <div class="cw-scrollwrap">
              <div class="cw-row" role="navigation" aria-label="Quick filters" data-cw-row>
                {{ pills_html }}
              </div>
            </div>
          </div>
        </div>
      {% endif %}
    </div>
  </section>

  {% if show_filters %}
    <script>
      (function () {
        document.querySelectorAll('[data-cw-header]').forEach(function(header) {
          if (header.dataset.cwInit === '1') return;
          header.dataset.cwInit = '1';

          var row = header.querySelector('[data-cw-row]');
          var btnL = header.querySelector('[data-cw-left]');
          var btnR = header.querySelector('[data-cw-right]');

          if (!row) return;

          var mq = window.matchMedia('(max-width: 768px)');
          var ticking = false;
          var lastSearch = window.location.search;

          function syncPills() {
            var params = new URLSearchParams(window.location.search);
            row.querySelectorAll('.cw-pill[data-filter-key]').forEach(function (pill) {
              var activeVals = params.getAll(pill.dataset.filterKey);
              pill.hidden = activeVals.indexOf(pill.dataset.filterVal) !== -1;
            });
          }

          function updateButtons() {
            if (!btnL || !btnR) return;
            if (mq.matches) { btnL.hidden = true; btnR.hidden = true; return; }
            var maxScroll = row.scrollWidth - row.clientWidth;
            var hasOverflow = maxScroll > 6;
            btnL.hidden = !hasOverflow || row.scrollLeft <= 6;
            btnR.hidden = !hasOverflow || row.scrollLeft >= (maxScroll - 6);
          }

          function requestUpdate() {
            if (ticking) return;
            ticking = true;
            requestAnimationFrame(function () { ticking = false; updateButtons(); });
          }

          function onUrlChange() {
            if (window.location.search !== lastSearch) {
              lastSearch = window.location.search;
              syncPills();
              requestUpdate();
            }
          }

          ['pushState', 'replaceState'].forEach(function (method) {
            var orig = history[method];
            history[method] = function () {
              orig.apply(this, arguments);
              onUrlChange();
            };
          });

          setInterval(onUrlChange, 300);
          window.addEventListener('popstate', function () { onUrlChange(); });
          ['filters:updated', 'collection:updated', 'facets:updated'].forEach(function (evt) {
            document.addEventListener(evt, function () { syncPills(); requestUpdate(); });
          });

          row.addEventListener('scroll', requestUpdate, { passive: true });

          if (btnL) btnL.addEventListener('click', function () { row.scrollBy({ left: -Math.max(160, Math.floor(row.clientWidth * 0.82)), behavior: 'smooth' }); });
          if (btnR) btnR.addEventListener('click', function () { row.scrollBy({ left: Math.max(160, Math.floor(row.clientWidth * 0.82)), behavior: 'smooth' }); });

          row.addEventListener('click', function (event) {
            var pill = event.target.closest('.cw-pill[data-filter-val]');
            if (!pill) return;
            event.preventDefault();
            var next = new URL(pill.getAttribute('href'), window.location.origin);
            next.searchParams.delete('page');
            window.location.href = next.toString();
          });

          window.addEventListener('resize', requestUpdate, { passive: true });
          if (mq.addEventListener) { mq.addEventListener('change', requestUpdate); }
          else if (mq.addListener) { mq.addListener(requestUpdate); }

          syncPills();
          requestUpdate();
          setTimeout(requestUpdate, 120);
        });
      })();
    </script>
  {% endif %}
{% endif %}

{%- liquid
  assign p = closest.product | default: product | default: card_product | default: product_resource
  assign variant = p.selected_or_first_available_variant

  assign tiers = blank
  assign max_bp = 0
  assign is_price_on_request = false

  if p != blank
    assign mf = p.metafields.custom.volume_discounts
    if mf != blank
      assign v = mf.value
      if v != blank and v.tiers != blank
        assign tiers = v.tiers
      else
        assign s = v | default: mf | to_s
        if s != blank
          assign parsed = s | parse_json
          if parsed != blank and parsed.tiers != blank
            assign tiers = parsed.tiers
          endif
        endif
      endif
    endif

    if tiers != blank
      for t in tiers
        assign d = t.discount | default: 0 | plus: 0
        if d > 1
          assign d = d | divided_by: 100.0
        endif
        assign bp = d | times: 10000 | round
        if bp > 9900
          assign bp = 9900
        endif
        if bp > max_bp
          assign max_bp = bp
        endif
      endfor
    endif

    assign base_incl = p.price_min
    assign factor_bp = 10000 | minus: max_bp
    assign from_incl = base_incl | times: factor_bp | divided_by: 10000

    if base_incl <= 2 or from_incl <= 2
      assign is_price_on_request = true
    endif
  endif

  assign status_text = 'Op voorraad'

  if p == blank or variant == blank or is_price_on_request
    assign status_text = 'Snelle afhandeling'
  else
    if variant.inventory_management == 'shopify'
      if variant.inventory_quantity > 0
        assign status_text = 'Op voorraad'
      else
        if variant.inventory_policy == 'continue'
          assign status_text = 'Snelle afhandeling'
        else
          assign status_text = 'Snelle afhandeling'
        endif
      endif
    else
      assign status_text = 'Op voorraad'
    endif
  endif
-%}

<div class="stock-status">
