<script>
  (function () {
    const stockLabels = document.querySelectorAll('.js-dynamic-stock-text');
    if (stockLabels.length === 0) return;

    const now = new Date();
    const day = now.getDay();
    const hour = now.getHours();

    const isWeekday = day >= 1 && day <= 5;
    const beforeFive = hour < 17;

    if (!isWeekday || !beforeFive) return;

    stockLabels.forEach(function(label) {
      if (label.textContent.trim() === 'Op voorraad') {
        label.textContent = 'Vandaag verzonden';
      }
    });
  })();
</script>

{% liquid
  assign raw_uid = block.id | default: section.id | default: 'diagonal-banner'
  assign uid = raw_uid | replace: ':', '-' | replace: '.', '-' | replace: '/', '-'

  assign banner_h = 380
  assign diag_top_x = 5
  assign diag_bottom_x = 250
  assign fold_w = 28
  assign band_w = 44
  assign band_top_y = 62

  assign delta = diag_bottom_x | minus: diag_top_x
  assign diag_at_band_y = delta | times: band_top_y | divided_by: banner_h | plus: diag_top_x

  assign image_obj = blank

  if collection and collection.metafields.custom.afbeelding and collection.metafields.custom.afbeelding.value != blank
    assign image_obj = collection.metafields.custom.afbeelding.value
  elsif collection and collection.image
    assign image_obj = collection.image
  elsif collection and collection.products_count > 0 and collection.products.first and collection.products.first.featured_image
    assign image_obj = collection.products.first.featured_image
  endif

  assign image_alt = collection.title | default: 'Collectie afbeelding'

  assign title = collection.title | append: ' op maat'
  assign subtitle = 'BouwmarktXL denkt graag mee'
  assign description = 'Maatwerk en oplossingsgericht advies behoren tot onze sterkste punten. Kun je voor jouw toepassing niet het juiste product of een passende oplossing vinden? Neem dan gerust contact met ons op.'
  assign button_label = 'Contact opnemen'
  assign button_link = '/pages/maatwerk'

  assign img_url_700 = blank
  assign img_url_mobile = blank
  if image_obj
    assign img_url_700 = image_obj | image_url: width: 1400
    assign img_url_mobile = image_obj | image_url: width: 800
  endif
%}

<style>
.rt-{{ uid }} {
  --rt-bg: #003878;
  --rt-btn-bg: #FF7300;
  --rt-btn-hover: #e66700;
  --rt-btn-text: #ffffff;
  --rt-text: #ffffff;
