}

@media (min-width: 768px) {
  .rt-{{ uid }} .rt-left {
    width: 50%;
    padding: 48px;
  }
}

.rt-{{ uid }} .rt-content {
  width: 100%;
  max-width: 820px;
}

.rt-{{ uid }} .rt-head {
  font-size: 32px;
  margin: 0 0 24px;
  color: #fff;
}

.rt-{{ uid }} .rt-head-line {
  display: block;
}

.rt-{{ uid }} .rt-head-line + .rt-head-line {
  margin-top: 8px;
}

.rt-{{ uid }} .rt-desc {
  font-size: 16px;
  max-width: 600px;
  margin: 0 0 24px;
  color: #fff;
}

.rt-{{ uid }} .rt-btn {
  display: inline-block;
  padding: 16px 24px;
  background: var(--rt-btn-bg);
