</style>

<div class="rt-wrap rt-{{ uid }}" style="content-visibility:auto; contain-intrinsic-size: 380px;">
  <div class="rt-banner">
    <div class="rt-left">
      <div class="rt-content">
        <h2 class="rt-head">
          <span class="rt-head-line">{{ title }}</span>
          <span class="rt-head-line">{{ subtitle }}</span>
        </h2>

        <p class="rt-desc">{{ description }}</p>

        <a href="{{ button_link }}" class="rt-btn">{{ button_label }}</a>
      </div>
    </div>

    <div class="rt-right">
      <svg viewBox="0 0 700 {{ banner_h }}" preserveAspectRatio="xMinYMid slice" aria-hidden="true">
        <defs>
          <clipPath id="imgClip-{{ uid }}">
            <polygon points="{{ diag_top_x }},0 700,0 700,{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}"></polygon>
          </clipPath>
          <clipPath id="shadowOnPhotoSide-{{ uid }}">
            <polygon points="{{ diag_top_x }},0 700,0 700,{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}"></polygon>
          </clipPath>

          <filter id="sh_fold_soft-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow dx="24" dy="1" stdDeviation="16" flood-color="#000" flood-opacity="0.14"/>
          </filter>

          <filter id="sh_band_only-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow in="SourceAlpha" dx="27" dy="17" stdDeviation="4.8" flood-color="#000" flood-opacity="0.22" result="ds1"/>
            <feDropShadow in="SourceAlpha" dx="52" dy="30" stdDeviation="26" flood-color="#000" flood-opacity="0.12" result="ds2"/>
            <feMerge>
              <feMergeNode in="ds1"/>
              <feMergeNode in="ds2"/>
            </feMerge>
          </filter>

          <linearGradient id="bandShine-{{ uid }}" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stop-color="#ffffff" stop-opacity="0.00"/>
            <stop offset="25%" stop-color="#ffffff" stop-opacity="0.22"/>
            <stop offset="50%" stop-color="#ffffff" stop-opacity="0.06"/>
            <stop offset="75%" stop-color="#ffffff" stop-opacity="0.18"/>
            <stop offset="100%" stop-color="#ffffff" stop-opacity="0.00"/>
          </linearGradient>

          <clipPath id="bandClip-{{ uid }}">
            <polygon points="{{ diag_at_band_y }},{{ band_top_y }} {{ diag_at_band_y | plus: band_w }},{{ band_top_y }} {{ diag_bottom_x | plus: band_w }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}"></polygon>
          </clipPath>
        </defs>

        {% if img_url_700 != blank %}
          <image
            data-href="{{ img_url_700 }}"
            x="0"
            y="0"
            width="700"
            height="{{ banner_h }}"
            clip-path="url(#imgClip-{{ uid }})"
            preserveAspectRatio="xMidYMid slice"
          />
        {% else %}
          <rect x="0" y="0" width="700" height="{{ banner_h }}" fill="#eee" clip-path="url(#imgClip-{{ uid }})" />
        {% endif %}

        <polygon points="{{ diag_at_band_y }},{{ band_top_y }} {{ diag_at_band_y | plus: band_w }},{{ band_top_y }} {{ diag_bottom_x | plus: band_w }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}" fill="#000" filter="url(#sh_band_only-{{ uid }})"/>
        <polygon points="{{ diag_at_band_y }},{{ band_top_y }} {{ diag_at_band_y | plus: band_w }},{{ band_top_y }} {{ diag_bottom_x | plus: band_w }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}" fill="#008CD2"/>

        <g clip-path="url(#bandClip-{{ uid }})" opacity="0.9">
          <rect x="0" y="0" width="700" height="{{ banner_h }}" fill="url(#bandShine-{{ uid }})"/>
        </g>

        <g clip-path="url(#shadowOnPhotoSide-{{ uid }})">
          <g filter="url(#sh_fold_soft-{{ uid }})">
            <polygon points="{{ diag_top_x | minus: fold_w }},0 {{ diag_top_x }},0 {{ diag_bottom_x }},{{ banner_h }} {{ diag_bottom_x | minus: fold_w }},{{ banner_h }}" fill="#003878"/>
          </g>
        </g>

        <polygon points="{{ diag_top_x | minus: fold_w }},0 {{ diag_top_x }},0 {{ diag_bottom_x }},{{ banner_h }} {{ diag_bottom_x | minus: fold_w }},{{ banner_h }}" fill="#003878"/>
        <polygon points="{{ diag_top_x }},0 {{ diag_top_x | plus: 2 }},0 {{ diag_bottom_x | plus: 2 }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}" fill="#000" opacity="0.06"/>
      </svg>

      {% if img_url_mobile != blank %}
        <img
          src="{{ img_url_mobile }}"
          class="rt-mobile-img"
          alt="{{ image_alt | escape }}"
          loading="lazy"
          decoding="async"
          fetchpriority="low"
          width="800"
          height="380"
        >
      {% else %}
        <div class="rt-mobile-img" style="background:#eee;"></div>
      {% endif %}
    </div>
  </div>
</div>

{% if img_url_700 != blank %}
  <script>
    (function() {
      var wrap = document.querySelector('.rt-{{ uid }}');
      if (!wrap) return;

      var svgImage = wrap.querySelector('image[data-href]');
      if (!svgImage) return;

      function loadSvgImage() {
        if (!svgImage.getAttribute('href')) {
          svgImage.setAttribute('href', svgImage.getAttribute('data-href'));
        }
      }

      if (!('IntersectionObserver' in window)) {
        loadSvgImage();
        return;
      }

      var observer = new IntersectionObserver(function(entries) {
        if (entries[0] && entries[0].isIntersecting) {
          loadSvgImage();
          observer.disconnect();
        }
      }, {
        rootMargin: '300px 0px'
      });

      observer.observe(wrap);
    })();
  </script>
{% endif %}

